mapper.select:
select
    a.record_id,
    a.record_name,
    a.recorder_model,
    a.recorder_type,
    a.vendor_id,
    a.pms_id,
    a.alias_name,
    a.record_ip,
    a.protocol,
    a.http_port,
    a.trans_port,
    a.rtsp_port,
    a.identity_manager,
    a.identity_code,
    a.protocol_url,
    a.max_channel,
    a.hdd_size,
    a.buffer_day,
    a.time_long,
    a.unit
from t_camera_recorder a
where 1 = 1
 and a.record_id = #{recordId, jdbcType=BIGINT}
 and a.record_name LIKE concat('%',#{recordName, jdbcType=VARCHAR},'%')
 and a.recorder_model = #{recorderModel, jdbcType=INTEGER}
 and a.recorder_type = #{recorderType, jdbcType=VARCHAR}
 and a.vendor_id = #{vendorId, jdbcType=INTEGER}
 and a.pms_id = #{pmsId, jdbcType=VARCHAR}
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.record_ip = #{recordIp, jdbcType=VARCHAR}
 and a.protocol = #{protocol, jdbcType=VARCHAR}
 and a.http_port = #{httpPort, jdbcType=INTEGER}
 and a.trans_port = #{transPort, jdbcType=INTEGER}
 and a.rtsp_port = #{rtspPort, jdbcType=INTEGER}
 and a.identity_manager = #{identityManager, jdbcType=VARCHAR}
 and a.identity_code = #{identityCode, jdbcType=VARCHAR}
 and a.protocol_url = #{protocolUrl, jdbcType=VARCHAR}
 and a.max_channel = #{maxChannel, jdbcType=INTEGER}
 and a.hdd_size = #{hddSize, jdbcType=INTEGER}
 and a.buffer_day = #{bufferDay, jdbcType=INTEGER}
 and a.time_long = #{timeLong, jdbcType=INTEGER}
 and a.unit = #{unit, jdbcType=VARCHAR}

select
from t_camera_recorder a
left join t_dict_business b on b.dict_code = a.recorder_type and b.col_name = 'recorder_type'
left join t_dict_business d on d.dict_code = a.protocol and d.col_name = 'protocol_type'
left join t_dict_business e on e.dict_code = a.vendor_id and e.col_name = 'camera_vendor'
left join t_dict_business f on f.dict_code = a.recorder_model and f.col_name = 'recorder_model'
where 1 = 1
 and a.record_name LIKE concat('%',#{recordName, jdbcType=VARCHAR},'%')
 and a.recorder_model = #{recorderModel, jdbcType=INTEGER}
 and a.vendor_id = #{vendorId, jdbcType=INTEGER}
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.unit = #{unit, jdbcType=VARCHAR}
